import { useEffect, useRef, useState } from "react";
import { api, money } from "@/lib/api";
import { MapPin, Navigation, Wallet } from "lucide-react";
import { toast } from "sonner";
import { DriverExpensesPortal } from "@/components/DriverExpensesPortal";

export default function StaffPortal() {
  const [data, setData] = useState(null);
  const [tracking, setTracking] = useState(null);
  const watchRef = useRef(null);
  const load = async () => {
    try { setData((await api.get("/my-work")).data); } catch (error) { toast.error(error.response?.data?.detail || "Portal unavailable"); }
  };
  useEffect(() => { load(); return () => { if (watchRef.current !== null) navigator.geolocation.clearWatch(watchRef.current); }; }, []);
  const startTracking = (loadId) => {
    if (!navigator.geolocation) { toast.error("GPS is not supported on this device"); return; }
    setTracking(loadId);
    watchRef.current = navigator.geolocation.watchPosition(async (position) => {
      if (position.coords.accuracy > 200) return;
      try { await api.post(`/my-work/loads/${loadId}/location`, { lat: position.coords.latitude, lon: position.coords.longitude, accuracy_m: position.coords.accuracy, recorded_at: new Date(position.timestamp).toISOString() }); load(); }
      catch (error) { toast.error(error.response?.data?.detail || "Location was not saved"); }
    }, () => toast.error("Location permission is required"), { enableHighAccuracy: true, maximumAge: 10000, timeout: 20000 });
  };
  const stopTracking = () => { if (watchRef.current !== null) navigator.geolocation.clearWatch(watchRef.current); watchRef.current = null; setTracking(null); };
  if (!data) return <div className="p-6 text-slate-400">Loading private workspace…</div>;
  if (data.role === "driver") return <DriverExpensesPortal data={data} tracking={tracking} startTracking={startTracking} stopTracking={stopTracking} onRefresh={load} routePdfUrl="/api/my-work/route.pdf" />;
  if (data.role === "dispatcher") return <div className="p-5 lg:p-8 max-w-4xl"><div className="text-xs uppercase font-mono tracking-widest text-slate-400">Private dispatcher workspace</div><h1 className="font-display text-4xl font-black mt-2">{data.dispatcher.name}</h1><div className="mt-2"><a data-testid="dispatcher-route-pdf" href={`${window.location.origin}/api/my-work/route.pdf`} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 px-3 py-2 rounded-lg border border-emerald-500/40 bg-emerald-500/10 text-emerald-300 text-xs font-semibold"><Navigation className="h-4 w-4" /> Download route sheet</a></div><div data-testid="dispatcher-payment-total" className="mt-6 text-3xl font-mono text-emerald-400">{money(data.payment_total)}</div><div className="text-sm text-slate-400">Total dispatcher payments</div><section className="mt-8"><div className="text-xs uppercase font-mono tracking-widest text-slate-400">Assigned driver routes</div><div className="mt-3 space-y-3">{data.loads.length === 0 && <div className="text-sm text-slate-500 border border-dashed border-slate-800 rounded-lg p-5">No loads are assigned to your drivers.</div>}{data.loads.map((loadItem) => <article key={loadItem.id} data-testid={`dispatcher-load-${loadItem.id}`} className="border border-slate-800 rounded-xl p-4"><div className="flex items-start justify-between gap-3"><div><div className="font-mono font-bold">{loadItem.load_number} <span className="text-slate-500">· {loadItem.status}</span></div><div className="mt-1 text-sm text-slate-300">{loadItem.driver_name || "Assigned driver"}</div><div className="mt-2 text-sm text-slate-400">{loadItem.origin} → {loadItem.destination}</div></div><a data-testid={`dispatcher-route-${loadItem.id}`} href={`https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(loadItem.origin || "")}&destination=${encodeURIComponent(loadItem.destination || "")}`} target="_blank" rel="noreferrer" className="shrink-0 px-3 py-2 rounded-lg border border-orange-500/40 text-orange-400 text-xs font-semibold inline-flex gap-1"><Navigation className="h-4 w-4" /> Route</a></div></article>)}</div></section><section className="mt-8"><div className="text-xs uppercase font-mono tracking-widest text-slate-400">Payments</div><div className="mt-3 space-y-2">{data.payments.map((payment) => <div key={payment.id} className="border border-slate-800 rounded-lg p-4 flex justify-between"><span>{payment.driver_name || "Settlement"} · {payment.paid_date || payment.created_at?.slice(0, 10)}</span><b className="font-mono">{money(payment.amount)}</b></div>)}</div></section></div>;
  return <div className="p-5 lg:p-8 max-w-4xl"><div className="text-xs uppercase font-mono tracking-widest text-slate-400">Private driver workspace</div><h1 className="font-display text-4xl font-black mt-2">{data.driver.name}</h1><div className="mt-2"><a data-testid="driver-route-pdf" href={`${window.location.origin}/api/my-work/route.pdf`} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 px-3 py-2 rounded-lg border border-emerald-500/40 bg-emerald-500/10 text-emerald-300 text-xs font-semibold"><Navigation className="h-4 w-4" /> Download my route sheet</a></div><div className="grid grid-cols-2 gap-3 mt-6"><div className="border border-slate-800 rounded-lg p-4"><Wallet className="h-4 w-4 text-emerald-400" /><div className="font-mono text-xl mt-3">{money(data.settlement_net_total)}</div><div className="text-xs text-slate-400">Settlement net total</div></div><div className="border border-slate-800 rounded-lg p-4"><Navigation className="h-4 w-4 text-cyan-400" /><div className="font-mono text-xl mt-3">{money(data.load_revenue_total)}</div><div className="text-xs text-slate-400">Assigned load revenue</div></div></div><div className="mt-6 space-y-3">{data.loads.map((loadItem) => <section key={loadItem.id} data-testid={`driver-load-${loadItem.id}`} className="border border-slate-800 rounded-xl p-4"><div className="font-mono font-bold">{loadItem.load_number} <span className="text-slate-400">· {loadItem.status}</span></div><div className="text-sm text-slate-300 mt-1">{loadItem.origin} → {loadItem.destination}</div><div className="text-xs text-slate-500 mt-2">Actual distance: {Math.round((loadItem.actual_meters || 0) / 1609.344 * 10) / 10} mi</div><button data-testid={`driver-track-${loadItem.id}`} onClick={() => tracking === loadItem.id ? stopTracking() : startTracking(loadItem.id)} className="mt-3 px-3 py-2 rounded-lg bg-orange-500 text-white text-sm font-semibold inline-flex gap-2"><MapPin className="h-4 w-4" />{tracking === loadItem.id ? "Stop sharing location" : "Start live location"}</button></section>)}</div></div>;
}